import os, re

# Search recursively for Demo pair patterns
search_dirs = [
    "/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference/play/users/u022",
]

found_files = []
for d in search_dirs:
    for root, dirs, files in os.walk(d):
        # Skip common directories we don't care about
        if 'site-packages' in root or '__pycache__' in root or '.git' in root:
            continue
        for f in files:
            if f.endswith('.jsonl') or f.endswith('.json'):
                filepath = os.path.join(root, f)
                try:
                    with open(filepath) as fh:
                        content = fh.read()
                        if 'Demo pair' in content and filepath not in found_files:
                            found_files.append(filepath)
                            print(f"Found in: {filepath}")
                except Exception as e:
                    pass

print("\nTotal files containing 'Demo pair':", len(found_files))

